# Code to convert multigroup cross sections generated by SCONE into corrected scattering cross sections and scattering multiplicity for use in multigroup calculations by SCONE
# It currently only works for cross sections generated using a materialMap or no spatial map


import os
import json
from decimal import Decimal as dc
from viz_neutronics.input2json import dict2obj
# from input2json import dict2obj # when running test within this script
import numpy as np



def generate_mg_XS(filepath_MC_output : str, tcType : str):
    """
    Summary: This script works for Material Maps. If there is no material map...
    filepath_MC_output (str) : The filepath to the Monte Carlo output file containing multigroup cross sections
    tcType (str) : Transport correction type. Can be either 'flux limited' or 'outscatter'

    """
    print('Applying ' + tcType + ' transport correction to multigroup cross sections')
    # read in MC output file (json)
    with open(filepath_MC_output) as f:
        outputDict = json.load(f)

    # read in the relevant parameters from the MC output file

    MC_output = dict2obj(outputDict)

    sm = MC_output.active.scatteringMatrices

    EnergyBounds = np.array(sm.EnergyBounds)

    if hasattr(sm, "MaterialBins") == True:

        MaterialBins = np.array(sm.MaterialBins)     
        
        # useful quantities
        numGroups = len(EnergyBounds[1])
        numMat = len(MaterialBins)
        
    else:
   
        MaterialBins = ['material'] # for a single material
        numGroups = len(EnergyBounds[0])
        numMat = 1
    print('{:.0f} energy groups,{:.0f} material (s)'.format(numGroups, numMat))


    capture = np.array(sm.capture)[...,0]
    fission = np.array(sm.fission)[...,0]
    transportFluxLimited = np.array(sm.transportFluxLimited)[...,0]
    transportOutScatter = np.array(sm.transportOutScatter)[...,0]
    nu = np.array(sm.nu)[...,0]
    chi = np.array(sm.chi)[...,0]
    P0 = np.array(sm.P0)[...,0]
    prod = np.array(sm.prod)[...,0]

    print('Capture XS')
    print(capture)

    if hasattr(sm, 'P1'):
        P1 = np.array(sm.P1)
        P2 = np.array(sm.P2)
        P3 = np.array(sm.P3)
        P4 = np.array(sm.P4)
        P5 = np.array(sm.P5)
        P6 = np.array(sm.P6)
        P7 = np.array(sm.P7)
    else:
        print('No higher order PN results found')

    # reshape scattering XS and scattering multiplicity arrays

    P0 = np.reshape(P0, (numMat, numGroups,numGroups))
    prod = np.reshape(prod, (numMat, numGroups,numGroups))

    # calculate total XS
    scatter = np.sum(P0,-1) # sum along each row of the scattering matrix to get the total scatter cross section
    total = fission + capture + scatter

    # calculate transport correction
    correction_FluxLimited = total - transportFluxLimited
    correction_OutScatter = total - transportOutScatter

    # apply transport correction
    P0_corrected = P0
    prod_corrected = prod
    for g in range(numGroups):
    
        if tcType == 'outscatter':
            P0_corrected[..., g,g] = P0[..., g,g] - correction_OutScatter[..., g]
        elif tcType == 'flux limited':
            P0_corrected[..., g,g] = P0[..., g,g] - correction_FluxLimited[..., g]
        else:
            raise ValueError('No correction to scattering cross section was applied')

        prod_corrected[..., g,g] = (prod[..., g,g] - 1) * P0[..., g,g] / P0_corrected[..., g,g] + 1

    print('P0 corrected')
    print(P0_corrected)

    # writes an output file for each material name material1, material2 etc.

    newpath = 'materialsInputs'
    if not os.path.exists(newpath):
        os.makedirs(newpath)


    for matIndex in range(numMat):
        if numMat == 1:
            
            mat = MaterialBins[matIndex]
            f = open(newpath + '/' + mat, "w")

            f.write('\nnumberOfGroups '+ str(numGroups) + ';')
            f.write('\ncapture    (' + str(capture).replace('[','').replace(']','') + ');')
            f.write('\nfission   (' + str(fission).replace('[','').replace(']','') + ');')
            f.write('\nnu ('+ str(nu).replace('[','').replace(']','') + ');')
            f.write('\nchi ('+ str(chi).replace('[','').replace(']','') + ');')
            f.write('\nscatteringMultiplicity ('+ str(prod.flatten()).replace('[','').replace(']','') + ');')
            f.write('\nP0 ('+ str(P0_corrected.flatten()).replace('[','').replace(']','') + ');')
            f.write('\n' +r'//') # for some reason the file won't run unless these comment signs are at the bottom
        
        elif numMat > 1:
            [mat] = MaterialBins[matIndex] 

            f = open(newpath + '/' + mat, "w")
            
            f.write('\nnumberOfGroups '+ str(numGroups) + ';')
            f.write('\ncapture    (' + str(capture[matIndex]).replace('[','').replace(']','') + ');')
            f.write('\nfission   (' + str(fission[matIndex]).replace('[','').replace(']','') + ');')
            f.write('\nnu ('+ str(nu[matIndex]).replace('[','').replace(']','') + ');')
            f.write('\nchi ('+ str(chi[matIndex]).replace('[','').replace(']','') + ');')
            f.write('\nscatteringMultiplicity ('+ str(prod[matIndex].flatten()).replace('[','').replace(']','') + ');')
            f.write('\nP0 ('+ str(P0_corrected[matIndex].flatten()).replace('[','').replace(']','') + ');')
            f.write('\n' +r'//') # for some reason the file won't run unless these comment signs are at the bottom





